+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Filter applied by the backend: every whitespace-separated name term must occur in the
+ * first or last name (ignoring case and accents), and the status must be one of
+ * {@code statuses} when that set is not empty.
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    public boolean matches(Customer c) {
+        if (!statuses.isEmpty() && !statuses.contains(c.status())) {
+            return false;
+        }
+        String trimmed = name.strip();
+        if (trimmed.isEmpty()) {
+            return true;
+        }
+        String first = fold(c.firstName());
+        String last = fold(c.lastName());
+        for (String term : trimmed.split("\\s+")) {
+            String t = fold(term);
+            if (!first.contains(t) && !last.contains(t)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private static String fold(String s) {
+        return Normalizer.normalize(s, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
